package com.thakur.employee.controller; import com.thakur.employee.dto.AuthDtos.*;import com.thakur.employee.repository.UserRepository;import com.thakur.employee.security.JwtService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController {private final AuthenticationManager auth;private final JwtService jwt;private final UserRepository users;@PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password()));var u=users.findByEmail(r.email()).orElseThrow();return new AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.getDepartment());}}
